def seed_and_link_expense_categories(apps, schema_editor):
    Expense = apps.get_model("expenses", "Expense")
    ExpenseCategory = apps.get_model("expenses", "ExpenseCategory")
    pairs = Expense.objects.values_list("organization_id", "category").distinct()
    for organization_id, code in pairs.iterator():
        if not code:
            continue
        category, _ = ExpenseCategory.objects.get_or_create(
            organization_id=organization_id,
            code=code,
            defaults={"name": code.replace("_", " ").title()},
        )
        Expense.objects.filter(
            organization_id=organization_id,
            category=code,
            expense_category__isnull=True,
        ).update(expense_category_id=category.pk)


